& $py -X utf8 -u postfit.py --phase combine --dataset beijing --epochs .25 1 3
& $py -X utf8 -u postfit.py --phase controls --dataset beijing --epochs .25 1 3
& $py -X utf8 -u postfit.py --phase ordered --dataset beijing --epochs .25 1 3
& $py -X utf8 -u postfit.py --phase predict --dataset electricity
& $py -X utf8 -u postfit.py --phase combine --dataset electricity --epochs .25 1 3
& $py -X utf8 -u postfit.py --phase controls --dataset electricity --epochs .25 1 3
& $py -X utf8 -u postfit.py --phase ordered --dataset electricity --epochs .25 1 3
& $py -X utf8 -u postfit.py --phase predict --dataset jena
& $py -X utf8 -u postfit.py --phase combine --dataset jena --epochs .25 1 3
& $py -X utf8 -u postfit.py --phase controls --dataset jena --epochs .25 1 3
& $py -X utf8 -u postfit.py --phase ordered --dataset jena --epochs .25 1 3
& $py -X utf8 -u postfit.py --phase predict --dataset pems08
& $py -X utf8 -u postfit.py --phase combine --dataset pems08 --epochs .25 1 3
& $py -X utf8 -u postfit.py --phase controls --dataset pems08 --epochs .25 1 3
& $py -X utf8 -u postfit.py --phase ordered --dataset pems08 --epochs .25 1 3
& $py -X utf8 -u postfit.py --phase predict --dataset robin
}

# E0: 과거 B의 별도 개발 증거. 고정 E1-E4/T 선택에 되먹이지 않는다.
# 이전 RNG/sampler가 없으므로 과거 구간 전체의 exact resume라고 부르지 않는다.
& $py -X utf8 -u legacy_queue.py run --asset-root $assetRoot --cache-root $env:INFORMS_CACHE_ROOT --include-controls --endpoint 4800 --endpoint 9600 --endpoint 19200 --execute-training
